mapper.select:
SELECT 'TB_SL_OPP' AS "tableName",o.opp_id AS "targetKey",upper(f.key) AS item,f.value FROM tb_sl_opp o CROSS JOIN LATERAL jsonb_each_text(to_jsonb(o)) f WHERE o.opp_id=#{id}
UNION ALL SELECT 'TB_SL_OPP_NEED',n.opp_id||':'||n.need_sn,upper(f.key),f.value FROM tb_sl_opp_need n CROSS JOIN LATERAL jsonb_each_text(to_jsonb(n)) f WHERE n.opp_id=#{id}
UNION ALL SELECT 'TB_SL_TENT_ASGN',t.tent_id::text,upper(f.key),f.value FROM tb_sl_tent_asgn t CROSS JOIN LATERAL jsonb_each_text(to_jsonb(t)) f WHERE t.opp_id=#{id}
ORDER BY 1,2,3
